module popcount16 (
    input  logic [15:0] x,
    output logic [4:0]  count
);
    logic [1:0] l1 [8];
    logic [2:0] l2 [4];
    logic [3:0] l3 [2];

    always_comb begin
        for (int i = 0; i < 8; i++)
            l1[i] = {1'b0, x[2*i]} + {1'b0, x[2*i+1]};
        for (int i = 0; i < 4; i++)
            l2[i] = {1'b0, l1[2*i]} + {1'b0, l1[2*i+1]};
        for (int i = 0; i < 2; i++)
            l3[i] = {1'b0, l2[2*i]} + {1'b0, l2[2*i+1]};
        count = {1'b0, l3[0]} + {1'b0, l3[1]};
    end
endmodule

module rr_arbiter4 (
    input  logic       clk,
    input  logic       rst,   // synchronous, active high
    input  logic [3:0] req,
    output logic [3:0] gnt
);
    logic [1:0] last;
    logic [1:0] pick;
    logic       any;

    always_comb begin
        pick = 2'd0;
        any  = 1'b0;
        for (int k = 1; k <= 4; k++) begin
            logic [1:0] idx;
            idx = last + 2'(k);
            if (!any && req[idx]) begin
                pick = idx;
                any  = 1'b1;
            end
        end
    end

    always_ff @(posedge clk) begin
        if (rst) begin
            gnt  <= 4'b0000;
            last <= 2'd3;
        end else if (!any) begin
            gnt  <= 4'b0000;   // last is unchanged
        end else begin
            gnt  <= 4'b0001 << pick;
            last <= pick;
        end
    end
endmodule

module noc_router5 #(
    parameter logic [1:0] X = 2'd1,
    parameter logic [1:0] Y = 2'd1,
    parameter int PAYLOAD_W = 8
) (
    input  logic                       clk,
    input  logic                       rst,
    input  logic [4:0]                 in_valid,
    output logic [4:0]                 in_ready,
    input  logic [5*(4+PAYLOAD_W)-1:0]  in_flit,
    output logic [4:0]                 out_valid,
    input  logic [4:0]                 out_ready,
    output logic [5*(4+PAYLOAD_W)-1:0]  out_flit
);
    localparam int FLIT_W = 4 + PAYLOAD_W;
    localparam logic [2:0] NORTH      = 3'd0;
    localparam logic [2:0] SOUTH      = 3'd1;
    localparam logic [2:0] EAST       = 3'd2;
    localparam logic [2:0] WEST       = 3'd3;
    localparam logic [2:0] LOCAL_PORT = 3'd4;

    function automatic logic [2:0] succ(input logic [2:0] p);
        return (p == 3'd4) ? 3'd0 : p + 3'd1;
    endfunction

    logic [4:0][2:0]          route;
    logic [4:0][4:0]          req;
    logic [4:0][4:0]          gnt;
    logic [4:0]               can_acc;
    logic [4:0]               occ;
    logic [4:0][2:0]          src_q;
    logic [4:0][2:0]          cur;
    logic [4:0][2:0]          start;
    logic [4:0][2:0]          gidx;
    logic [4:0][FLIT_W-1:0]   data;
    logic [4:0][FLIT_W-1:0]   sel;

    for (genvar s = 0; s < 5; s++) begin : g_route
        wire [1:0] dest_x = in_flit[s*FLIT_W + PAYLOAD_W + 2 +: 2];
        wire [1:0] dest_y = in_flit[s*FLIT_W + PAYLOAD_W +: 2];
        assign route[s] = (dest_x > X) ? EAST :
                          (dest_x < X) ? WEST :
                          (dest_y > Y) ? NORTH :
                          (dest_y < Y) ? SOUTH : LOCAL_PORT;
    end

    for (genvar d = 0; d < 5; d++) begin : g_req
        for (genvar s = 0; s < 5; s++) begin : g_s
            assign req[d][s] = in_valid[s] && (route[s] == 3'(d));
        end
    end

    assign can_acc = {5{!rst}} & (~occ | out_ready);

    always_comb begin : arb
        logic found;
        int idx;
        for (int d = 0; d < 5; d++) begin
            start[d] = occ[d] ? succ(src_q[d]) : cur[d];
            found = 1'b0;
            gnt[d] = '0;
            gidx[d] = '0;
            for (int k = 0; k < 5; k++) begin
                idx = (int'(start[d]) + k) % 5;
                if (!found && req[d][idx]) begin
                    found = 1'b1;
                    gnt[d][idx] = 1'b1;
                    gidx[d] = 3'(idx);
                end
            end
            if (!can_acc[d]) gnt[d] = '0;
            sel[d] = '0;
            for (int s = 0; s < 5; s++) begin
                sel[d] |= in_flit[s*FLIT_W +: FLIT_W] & {FLIT_W{gnt[d][s]}};
            end
        end
        for (int s = 0; s < 5; s++) begin
            in_ready[s] = 1'b0;
            for (int d = 0; d < 5; d++) begin
                in_ready[s] = in_ready[s] | gnt[d][s];
            end
        end
    end

    assign out_valid = occ;
    assign out_flit  = data;

    always_ff @(posedge clk) begin
        if (rst) begin
            occ   <= '0;
            data  <= '0;
            src_q <= '0;
            cur   <= '0;
        end else begin
            for (int d = 0; d < 5; d++) begin
                if (can_acc[d]) begin
                    occ[d]  <= |gnt[d];
                    data[d] <= sel[d];
                    if (|gnt[d]) src_q[d] <= gidx[d];
                end
                if (occ[d] && out_ready[d]) begin
                    cur[d] <= succ(src_q[d]);
                end
            end
        end
    end
endmodule

